<?php require 'config.php';require 'includes/functions.php';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)flash('Enter valid details. Password must be at least 8 characters.','error');else{try{$s=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'customer')");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);flash('Account created. Please sign in.');go('login.php');}catch(PDOException $e){flash('That email is already registered.','error');}}}$title='Create account';require 'includes/header.php';?><div class="formbox"><span class="eyebrow">JOIN STYLEHUB</span><h1>Create your account</h1><form method="post"><?=csrf_field()?><label>Full name<input name="name" required></label><label>Email address<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="8" required></label><button class="button dark full">Create account</button></form><p>Already have an account? <a href="login.php">Sign in</a></p></div><?php require 'includes/footer.php';?>